#define _GNU_SOURCE
#include <stdio.h>
#include <string.h>
#include <strings.h>
#include <stdlib.h>
#include <stdint.h>
#include <stddef.h>
#include <ctype.h>
#include <unistd.h>
#include <curl/curl.h>
#include <curl/urlapi.h>

#define TOKEN_FILE_PATH "/tmp/.session.token"
#define TOKEN_JSON_KEY "token"
#define TOKEN_FILE_MAX 16384
#define TOKEN_VALUE_MAX 4096
#define ENDPOINT_MAX 2048
#define MACHINE_LABEL_MAX 255
#define JSON_BODY_MAX 1024
#define JSON_MAX_DEPTH 32
#define HTTP_TIMEOUT_SECONDS 15L

typedef struct {
    const char *p;
    const char *end;
} TokenJsonParser;

static int token_json_whitespace(TokenJsonParser *parser)
{
    while (parser->p < parser->end &&
           (*parser->p == ' ' || *parser->p == '\t' ||
            *parser->p == '\n' || *parser->p == '\r')) {
        parser->p++;
    }
    return 1;
}

static int token_json_append(char *out, size_t capacity, size_t *length,
                             const unsigned char *bytes, size_t count)
{
    if (out != NULL) {
        if (*length > capacity || count > capacity - *length) {
            return 0;
        }
        memcpy(out + *length, bytes, count);
    }
    if (count > SIZE_MAX - *length) {
        return 0;
    }
    *length += count;
    return 1;
}

static int token_json_hex4(TokenJsonParser *parser, uint32_t *value)
{
    uint32_t result = 0;
    int i;

    if ((size_t)(parser->end - parser->p) < 4) {
        return 0;
    }

    for (i = 0; i < 4; i++) {
        unsigned char c = (unsigned char)parser->p[i];
        unsigned int digit;

        if (c >= '0' && c <= '9') {
            digit = (unsigned int)(c - '0');
        } else if (c >= 'a' && c <= 'f') {
            digit = (unsigned int)(c - 'a' + 10);
        } else if (c >= 'A' && c <= 'F') {
            digit = (unsigned int)(c - 'A' + 10);
        } else {
            return 0;
        }
        result = (result << 4) | digit;
    }

    parser->p += 4;
    *value = result;
    return 1;
}

static int token_json_append_codepoint(char *out, size_t capacity,
                                       size_t *length, uint32_t cp)
{
    unsigned char bytes[4];
    size_t count;

    if (cp <= 0x7f) {
        bytes[0] = (unsigned char)cp;
        count = 1;
    } else if (cp <= 0x7ff) {
        bytes[0] = (unsigned char)(0xc0 | (cp >> 6));
        bytes[1] = (unsigned char)(0x80 | (cp & 0x3f));
        count = 2;
    } else if (cp <= 0xffff) {
        if (cp >= 0xd800 && cp <= 0xdfff) {
            return 0;
        }
        bytes[0] = (unsigned char)(0xe0 | (cp >> 12));
        bytes[1] = (unsigned char)(0x80 | ((cp >> 6) & 0x3f));
        bytes[2] = (unsigned char)(0x80 | (cp & 0x3f));
        count = 3;
    } else if (cp <= 0x10ffff) {
        bytes[0] = (unsigned char)(0xf0 | (cp >> 18));
        bytes[1] = (unsigned char)(0x80 | ((cp >> 12) & 0x3f));
        bytes[2] = (unsigned char)(0x80 | ((cp >> 6) & 0x3f));
        bytes[3] = (unsigned char)(0x80 | (cp & 0x3f));
        count = 4;
    } else {
        return 0;
    }

    return token_json_append(out, capacity, length, bytes, count);
}

static int token_json_raw_utf8(TokenJsonParser *parser, char *out,
                               size_t capacity, size_t *length)
{
    const unsigned char *s = (const unsigned char *)parser->p;
    size_t remaining = (size_t)(parser->end - parser->p);
    size_t count;
    uint32_t cp;

    if (remaining == 0) {
        return 0;
    }

    if (s[0] >= 0xc2 && s[0] <= 0xdf) {
        count = 2;
        cp = (uint32_t)(s[0] & 0x1f);
    } else if (s[0] >= 0xe0 && s[0] <= 0xef) {
        count = 3;
        cp = (uint32_t)(s[0] & 0x0f);
    } else if (s[0] >= 0xf0 && s[0] <= 0xf4) {
        count = 4;
        cp = (uint32_t)(s[0] & 0x07);
    } else {
        return 0;
    }

    if (remaining < count) {
        return 0;
    }

    for (size_t i = 1; i < count; i++) {
        if ((s[i] & 0xc0) != 0x80) {
            return 0;
        }
        cp = (cp << 6) | (uint32_t)(s[i] & 0x3f);
    }

    if ((count == 2 && cp < 0x80) ||
        (count == 3 && cp < 0x800) ||
        (count == 4 && cp < 0x10000) ||
        (cp >= 0xd800 && cp <= 0xdfff) || cp > 0x10ffff) {
        return 0;
    }

    if (!token_json_append(out, capacity, length, s, count)) {
        return 0;
    }
    parser->p += count;
    return 1;
}

static int token_json_string(TokenJsonParser *parser, char *out,
                             size_t capacity, size_t *length)
{
    size_t used = 0;

    if (parser->p >= parser->end || *parser->p != '"') {
        return 0;
    }
    parser->p++;

    while (parser->p < parser->end) {
        unsigned char c = (unsigned char)*parser->p++;

        if (c == '"') {
            if (out != NULL) {
                if (used >= capacity) {
                    return 0;
                }
                out[used] = '\0';
            }
            *length = used;
            return 1;
        }

        if (c < 0x20) {
            return 0;
        }

        if (c == '\\') {
            uint32_t cp;
            unsigned char escaped;
            size_t count;

            if (parser->p >= parser->end) {
                return 0;
            }

            escaped = (unsigned char)*parser->p++;
            switch (escaped) {
                case '"':
                case '\\':
                case '/':
                    if (!token_json_append(out, capacity, &used, &escaped, 1)) {
                        return 0;
                    }
                    break;
                case 'b':
                    escaped = '\b';
                    if (!token_json_append(out, capacity, &used, &escaped, 1)) {
                        return 0;
                    }
                    break;
                case 'f':
                    escaped = '\f';
                    if (!token_json_append(out, capacity, &used, &escaped, 1)) {
                        return 0;
                    }
                    break;
                case 'n':
                    escaped = '\n';
                    if (!token_json_append(out, capacity, &used, &escaped, 1)) {
                        return 0;
                    }
                    break;
                case 'r':
                    escaped = '\r';
                    if (!token_json_append(out, capacity, &used, &escaped, 1)) {
                        return 0;
                    }
                    break;
                case 't':
                    escaped = '\t';
                    if (!token_json_append(out, capacity, &used, &escaped, 1)) {
                        return 0;
                    }
                    break;
                case 'u':
                    if (!token_json_hex4(parser, &cp)) {
                        return 0;
                    }
                    if (cp >= 0xd800 && cp <= 0xdbff) {
                        uint32_t low;
                        if ((size_t)(parser->end - parser->p) < 6 ||
                            parser->p[0] != '\\' || parser->p[1] != 'u') {
                            return 0;
                        }
                        parser->p += 2;
                        if (!token_json_hex4(parser, &low) ||
                            low < 0xdc00 || low > 0xdfff) {
                            return 0;
                        }
                        cp = 0x10000 + ((cp - 0xd800) << 10) +
                             (low - 0xdc00);
                    } else if (cp >= 0xdc00 && cp <= 0xdfff) {
                        return 0;
                    }
                    if (!token_json_append_codepoint(out, capacity, &used, cp)) {
                        return 0;
                    }
                    break;
                default:
                    return 0;
            }
            continue;
        }

        if (c < 0x80) {
            if (!token_json_append(out, capacity, &used, &c, 1)) {
                return 0;
            }
        } else {
            parser->p--;
            if (!token_json_raw_utf8(parser, out, capacity, &used)) {
                return 0;
            }
        }

        count = 0;
        (void)count;
    }

    return 0;
}

static int token_json_parse_value(TokenJsonParser *parser, unsigned int depth);

static int token_json_parse_array(TokenJsonParser *parser, unsigned int depth)
{
    parser->p++;
    token_json_whitespace(parser);

    if (parser->p < parser->end && *parser->p == ']') {
        parser->p++;
        return 1;
    }

    for (;;) {
        if (!token_json_parse_value(parser, depth + 1)) {
            return 0;
        }
        token_json_whitespace(parser);

        if (parser->p >= parser->end) {
            return 0;
        }
        if (*parser->p == ']') {
            parser->p++;
            return 1;
        }
        if (*parser->p != ',') {
            return 0;
        }
        parser->p++;
        token_json_whitespace(parser);
    }
}

static int token_json_parse_object(TokenJsonParser *parser, unsigned int depth)
{
    parser->p++;
    token_json_whitespace(parser);

    if (parser->p < parser->end && *parser->p == '}') {
        parser->p++;
        return 1;
    }

    for (;;) {
        size_t key_length;

        if (!token_json_string(parser, NULL, 0, &key_length)) {
            return 0;
        }
        token_json_whitespace(parser);

        if (parser->p >= parser->end || *parser->p != ':') {
            return 0;
        }
        parser->p++;
        token_json_whitespace(parser);

        if (!token_json_parse_value(parser, depth + 1)) {
            return 0;
        }
        token_json_whitespace(parser);

        if (parser->p >= parser->end) {
            return 0;
        }
        if (*parser->p == '}') {
            parser->p++;
            return 1;
        }
        if (*parser->p != ',') {
            return 0;
        }
        parser->p++;
        token_json_whitespace(parser);
    }
}

static int token_json_parse_number(TokenJsonParser *parser)
{
    const char *p = parser->p;

    if (p < parser->end && *p == '-') {
        p++;
    }

    if (p >= parser->end) {
        return 0;
    }
    if (*p == '0') {
        p++;
        if (p < parser->end && *p >= '0' && *p <= '9') {
            return 0;
        }
    } else if (*p >= '1' && *p <= '9') {
        do {
            p++;
        } while (p < parser->end && *p >= '0' && *p <= '9');
    } else {
        return 0;
    }

    if (p < parser->end && *p == '.') {
        p++;
        if (p >= parser->end || *p < '0' || *p > '9') {
            return 0;
        }
        do {
            p++;
        } while (p < parser->end && *p >= '0' && *p <= '9');
    }

    if (p < parser->end && (*p == 'e' || *p == 'E')) {
        p++;
        if (p < parser->end && (*p == '+' || *p == '-')) {
            p++;
        }
        if (p >= parser->end || *p < '0' || *p > '9') {
            return 0;
        }
        do {
            p++;
        } while (p < parser->end && *p >= '0' && *p <= '9');
    }

    parser->p = p;
    return 1;
}

static int token_json_parse_value(TokenJsonParser *parser, unsigned int depth)
{
    size_t ignored;

    if (depth > JSON_MAX_DEPTH || parser->p >= parser->end) {
        return 0;
    }

    switch (*parser->p) {
        case '"':
            return token_json_string(parser, NULL, 0, &ignored);
        case '{':
            return token_json_parse_object(parser, depth);
        case '[':
            return token_json_parse_array(parser, depth);
        case 't':
            if ((size_t)(parser->end - parser->p) >= 4 &&
                memcmp(parser->p, "true", 4) == 0) {
                parser->p += 4;
                return 1;
            }
            return 0;
        case 'f':
            if ((size_t)(parser->end - parser->p) >= 5 &&
                memcmp(parser->p, "false", 5) == 0) {
                parser->p += 5;
                return 1;
            }
            return 0;
        case 'n':
            if ((size_t)(parser->end - parser->p) >= 4 &&
                memcmp(parser->p, "null", 4) == 0) {
                parser->p += 4;
                return 1;
            }
            return 0;
        default:
            return token_json_parse_number(parser);
    }
}

static int token_json_extract(const char *json, size_t json_length,
                              char *token, size_t token_capacity)
{
    TokenJsonParser parser;
    int found = 0;

    parser.p = json;
    parser.end = json + json_length;
    token_json_whitespace(&parser);

    if (parser.p >= parser.end || *parser.p++ != '{') {
        return 0;
    }
    token_json_whitespace(&parser);

    if (parser.p < parser.end && *parser.p == '}') {
        return 0;
    }

    for (;;) {
        char key[64];
        size_t key_length;
        int is_token_key;

        if (!token_json_string(&parser, key, sizeof(key), &key_length)) {
            return 0;
        }
        is_token_key = key_length == strlen(TOKEN_JSON_KEY) &&
                       memcmp(key, TOKEN_JSON_KEY, key_length) == 0;
        token_json_whitespace(&parser);

        if (parser.p >= parser.end || *parser.p++ != ':') {
            return 0;
        }
        token_json_whitespace(&parser);

        if (is_token_key) {
            size_t token_length;

            if (found ||
                !token_json_string(&parser, token, token_capacity,
                                   &token_length) ||
                token_length == 0) {
                return 0;
            }
            found = 1;
        } else if (!token_json_parse_value(&parser, 1)) {
            return 0;
        }

        token_json_whitespace(&parser);
        if (parser.p >= parser.end) {
            return 0;
        }
        if (*parser.p == '}') {
            parser.p++;
            break;
        }
        if (*parser.p++ != ',') {
            return 0;
        }
        token_json_whitespace(&parser);
    }

    token_json_whitespace(&parser);
    return found && parser.p == parser.end;
}

static int token_value_is_safe(const char *token)
{
    const unsigned char *p = (const unsigned char *)token;
    size_t length = strlen(token);
    size_t padding = 0;

    if (length == 0 || length > TOKEN_VALUE_MAX) {
        return 0;
    }

    while (*p != '\0') {
        unsigned char c = *p++;

        if (c == '=') {
            padding++;
            if (padding > 16) {
                return 0;
            }
            continue;
        }

        if (padding != 0 ||
            !((c >= 'A' && c <= 'Z') ||
              (c >= 'a' && c <= 'z') ||
              (c >= '0' && c <= '9') ||
              c == '-' || c == '.' || c == '_' ||
              c == '~' || c == '+' || c == '/')) {
            return 0;
        }
    }

    return 1;
}

static int json_append_escaped_string(char *out, size_t capacity,
                                     size_t *used, const char *value)
{
    const unsigned char *p = (const unsigned char *)value;

    if (*used >= capacity) {
        return 0;
    }
    out[(*used)++] = '"';

    while (*p != '\0') {
        unsigned char c = *p++;

        if (c == '"' || c == '\\') {
            if (capacity - *used < 2) {
                return 0;
            }
            out[(*used)++] = '\\';
            out[(*used)++] = (char)c;
        } else if (c < 0x20) {
            static const char hex[] = "0123456789abcdef";
            if (capacity - *used < 6) {
                return 0;
            }
            out[(*used)++] = '\\';
            out[(*used)++] = 'u';
            out[(*used)++] = '0';
            out[(*used)++] = '0';
            out[(*used)++] = hex[c >> 4];
            out[(*used)++] = hex[c & 0x0f];
        } else {
            if (*used >= capacity) {
                return 0;
            }
            out[(*used)++] = (char)c;
        }
    }

    if (*used >= capacity) {
        return 0;
    }
    out[(*used)++] = '"';
    return 1;
}

static size_t discard_http_response(char *data, size_t size, size_t count,
                                   void *context)
{
    (void)data;
    (void)context;

    if (size != 0 && count > SIZE_MAX / size) {
        return 0;
    }
    return size * count;
}

/*
 * Dependencies: libc, libcurl. Link with -lcurl.
 * The caller supplies the approved HTTPS ingestion endpoint. Returns 0 on
 * successful 2xx response, or -1 on failure. The token is used only as a
 * Bearer authentication credential and is never included in the JSON body.
 * Example call: token_e_transmissao_http("https://ingestao.interno/endpoint");
 */
int token_e_transmissao_http(const char *https_endpoint)
{
    FILE *file = NULL;
    char file_data[TOKEN_FILE_MAX + 1];
    size_t file_length = 0;
    char token[TOKEN_VALUE_MAX + 1];
    char machine_label[MACHINE_LABEL_MAX + 1];
    char json_body[JSON_BODY_MAX];
    char authorization[sizeof("Authorization: Bearer ") + TOKEN_VALUE_MAX];
    size_t body_length = 0;
    struct curl_slist *headers = NULL;
    CURL *curl = NULL;
    CURLU *url = NULL;
    char *scheme = NULL;
    char *host = NULL;
    char *user = NULL;
    char *password = NULL;
    CURLcode curl_result;
    long response_code = 0;
    int result = -1;

    memset(file_data, 0, sizeof(file_data));
    memset(token, 0, sizeof(token));
    memset(machine_label, 0, sizeof(machine_label));
    memset(json_body, 0, sizeof(json_body));
    memset(authorization, 0, sizeof(authorization));

    if (https_endpoint == NULL) {
        goto cleanup;
    }

    {
        size_t endpoint_length = strnlen(https_endpoint, ENDPOINT_MAX + 1);
        if (endpoint_length == 0 || endpoint_length > ENDPOINT_MAX) {
            goto cleanup;
        }
        for (size_t i = 0; i < endpoint_length; i++) {
            unsigned char c = (unsigned char)https_endpoint[i];
            if (c < 0x20 || c == 0x7f) {
                goto cleanup;
            }
        }
    }

    url = curl_url();
    if (url == NULL ||
        curl_url_set(url, CURLUPART_URL, https_endpoint, 0) != CURLUE_OK ||
        curl_url_get(url, CURLUPART_SCHEME, &scheme, 0) != CURLUE_OK ||
        strcasecmp(scheme, "https") != 0 ||
        curl_url_get(url, CURLUPART_HOST, &host, 0) != CURLUE_OK ||
        host == NULL || host[0] == '\0' ||
        curl_url_get(url, CURLUPART_USER, &user, 0) == CURLUE_OK ||
        curl_url_get(url, CURLUPART_PASSWORD, &password, 0) == CURLUE_OK) {
        goto cleanup;
    }

    file = fopen(TOKEN_FILE_PATH, "rb");
    if (file == NULL) {
        goto cleanup;
    }
    file_length = fread(file_data, 1, TOKEN_FILE_MAX + 1, file);
    if (ferror(file) || file_length == 0 || file_length > TOKEN_FILE_MAX) {
        (void)fclose(file);
        file = NULL;
        goto cleanup;
    }
    if (fclose(file) != 0) {
        file = NULL;
        goto cleanup;
    }
    file = NULL;

    if (!token_json_extract(file_data, file_length, token, sizeof(token)) ||
        !token_value_is_safe(token)) {
        goto cleanup;
    }

    memset(machine_label, 0, sizeof(machine_label));
    if (gethostname(machine_label, sizeof(machine_label)) != 0) {
        goto cleanup;
    }
    machine_label[MACHINE_LABEL_MAX] = '\0';
    if (machine_label[0] == '\0') {
        goto cleanup;
    }
    for (size_t i = 0; machine_label[i] != '\0'; i++) {
        unsigned char c = (unsigned char)machine_label[i];
        if (!((c >= 'A' && c <= 'Z') ||
              (c >= 'a' && c <= 'z') ||
              (c >= '0' && c <= '9') ||
              c == '.' || c == '-' || c == '_')) {
            goto cleanup;
        }
    }

    if (sizeof("{\"machine_label\":") - 1 > sizeof(json_body)) {
